INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $xw$cmxwatch1105hy4tencent01$xw$, $xw$tencent-hy4$xw$, $xw$Tencent Hy4$xw$, $xw$Tencent$xw$, $xw$https://openrouter.ai/tencent/hy4$xw$, NULL, $xw$Tencent's Hy4 large language model (announced 2026-11-04). It adds visual understanding and computer-use (CLI and GUI), with stronger long-context and long-horizon agent work. API pricing on Tencent Cloud TokenHub is about $0.90 input / $2.70 output / $0.045 cached input per 1M tokens; TokenHub lists 50% off those rates through 2026-12-31. On OpenRouter (tencent/hy4) the discounted Tencent Cloud rates shown were $0.417/$1.251 (cached $0.021) per 1M tokens with a 1,048,576-token context (as of 2026-11-05). Available on Tencent Cloud TokenHub, WorkBuddy, CodeBuddy, Yuanbao and third-party routers such as OpenRouter. Tencent says model weights and system cards are planned for release in the coming days (not confirmed available yet as of 2026-11-05). WorkBuddy and CodeBuddy were free from 2026-11-04 through 2026-11-15.$xw$, $xw$cmnxhfk4u004q88svb7gaw4ew$xw$, $xw$Open multimodal LLM with computer-use and 1M context via API$xw$, $xw$FREEMIUM$xw$::"CostTier", $xw$INTERMEDIATE$xw$::"Difficulty", ARRAY[$xw$api$xw$, $xw$web$xw$]::text[], $xw$TokenHub list about $0.90/$2.70 per 1M input/output ($0.045 cached input); 50% off through 2026-12-31. OpenRouter Tencent Cloud discounted rates $0.417/$1.251 ($0.021 cached) per 1M as of 2026-11-05; 1,048,576 context$xw$, $xw$Promo windows: WorkBuddy and CodeBuddy free 2026-11-04 to 2026-11-15; TokenHub 50% off through 2026-12-31 (as of 2026-11-05)$xw$, $xw$OpenRouter context 1,048,576 tokens; completion up to 65,536 on the OpenRouter listing (as of 2026-11-05)$xw$, NULL, $xw$Higher TokenHub volume after the 50% promo ends; paid WorkBuddy/CodeBuddy after the free window$xw$, $xw$API via Tencent Cloud TokenHub and routers such as OpenRouter (tencent/hy4)$xw$, false, true, $xw$Tencent Cloud TokenHub, WorkBuddy, CodeBuddy, Yuanbao, OpenRouter, Hermes, OpenCode$xw$, $xw$MEDIUM$xw$::"PrivacyLevel", ARRAY[$xw$developers$xw$, $xw$teams building agents$xw$, $xw$users who need Chinese and English productivity agents$xw$]::text[], $xw$Long-horizon agent tasks; visual understanding; computer use; coding and office workflows$xw$, NULL, $xw$Moderate$xw$, ARRAY[$xw$Kimi$xw$, $xw$MiniMax$xw$, $xw$OpenRouter$xw$]::text[], ARRAY[$xw$OpenRouter$xw$, $xw$Hermes Agent$xw$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$xw$Text$xw$, $xw$Images$xw$]::text[], ARRAY[$xw$Text$xw$]::text[], $xw$Strong Chinese and English; other languages not fully verified here (as of 2026-11-05)$xw$, false, true, now(), now(), false, NULL, NULL, true WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $xw$tencent-hy4$xw$) AND EXISTS (SELECT 1 FROM categories WHERE id = $xw$cmnxhfk4u004q88svb7gaw4ew$xw$);
INSERT INTO platforms ("id", "slug", "name", "company", "website", "logoUrl", "description", "categoryId", "primaryUse", "costTier", "difficultyLevel", "platformType", "currentPricing", "freeTierFeatures", "usageLimits", "qualityRestrictions", "upgradeTriggers", "installationType", "offlineCapable", "apiAvailable", "keyIntegrations", "privacyLevel", "idealUserTypes", "primaryUseCases", "timeToProductivity", "learningCurve", "directAlternatives", "complementaryTools", "budgetAlternativeTo", "privacyAlternativeTo", "contentTypes", "outputFormats", "languageSupport", "featured", "verified", "createdAt", "updatedAt", "hasMobileApp", "iosAppUrl", "androidAppUrl", "mobileWebFriendly") SELECT $xw$cmxwatch1105longcat2501$xw$, $xw$longcat-2-5$xw$, $xw$LongCat 2.5$xw$, $xw$Meituan$xw$, $xw$https://longcat.ai/$xw$, NULL, $xw$Meituan's LongCat-2.5 is a native multimodal model for long-horizon agent and coding work: about 1.6 trillion total parameters with roughly 48 billion active per token, a 1,048,576-token context, and text plus image input. It is aimed at complex codebases, full-project builds, visual coding, creative design and 3D tasks, and works with agent harnesses such as Claude Code, Codex and Hermes. Pay-as-you-go on the LongCat API Platform (limited-time discounted prices as of 2026-11-05): $0.30 input / $0.006 cached input / $1.20 output per 1M tokens (¥2 / ¥0.04 / ¥8). The same model id meituan/longcat-2.5 is on Vercel AI Gateway at those USD rates. LongCat-2.5 was not listed on OpenRouter at check time (OpenRouter showed LongCat 2.0); treat an OpenRouter 2.5 listing as unverified until it appears there.$xw$, $xw$cmnxhfk4u004q88svb7gaw4ew$xw$, $xw$Meituan multimodal coding and long-horizon agent model with API access$xw$, $xw$FREEMIUM$xw$::"CostTier", $xw$INTERMEDIATE$xw$::"Difficulty", ARRAY[$xw$api$xw$, $xw$web$xw$]::text[], $xw$LongCat API Platform PAYG (limited-time discount, as of 2026-11-05): $0.30 input / $0.006 cached / $1.20 output per 1M tokens (¥2 / ¥0.04 / ¥8). Also on Vercel AI Gateway as meituan/longcat-2.5 at the same USD rates; 1,048,576 context$xw$, $xw$LongCat Chat has historically offered free chat for some models; confirm current free chat for 2.5 on longcat.chat (unverified whether 2.5 itself is free in chat as of 2026-11-05)$xw$, $xw$1,048,576 context; Vercel AI Gateway lists max output 131,072 tokens (as of 2026-11-05)$xw$, NULL, $xw$Higher API volume on LongCat PAYG or Token Pack; enterprise verification for invoicing and tiered discounts$xw$, $xw$LongCat API Platform; Vercel AI Gateway model meituan/longcat-2.5; agent harnesses such as Claude Code, Codex, Hermes$xw$, false, true, $xw$LongCat API Platform, Vercel AI Gateway, Claude Code, Codex, Hermes$xw$, $xw$MEDIUM$xw$::"PrivacyLevel", ARRAY[$xw$software engineers$xw$, $xw$agent builders$xw$, $xw$teams needing multimodal coding models$xw$]::text[], $xw$Complex codebase work; full-project builds; visual coding; creative design and 3D agent tasks$xw$, NULL, $xw$Moderate$xw$, ARRAY[$xw$MiniMax$xw$, $xw$Kimi$xw$, $xw$OpenRouter$xw$]::text[], ARRAY[$xw$OpenRouter$xw$, $xw$Hermes Agent$xw$]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[$xw$Text$xw$, $xw$Images$xw$]::text[], ARRAY[$xw$Text$xw$, $xw$Code$xw$]::text[], $xw$Chinese and English primary; other languages not fully verified here (as of 2026-11-05)$xw$, false, true, now(), now(), false, NULL, NULL, true WHERE NOT EXISTS (SELECT 1 FROM platforms WHERE slug = $xw$longcat-2-5$xw$) AND EXISTS (SELECT 1 FROM categories WHERE id = $xw$cmnxhfk4u004q88svb7gaw4ew$xw$);

UPDATE platforms SET name = $xw$GPT Image 2.6 (Flare / Sunburst)$xw$, website = $xw$https://developers.openai.com/api/docs/models/gpt-image-2.6-flare$xw$, "currentPricing" = $xw$ChatGPT plans include image creation; API models gpt-image-2.6-flare and gpt-image-2.6-sunburst bill per token at $5 text in / $1.25 cached text in / $8 image in / $2 cached image in / $30 image out per 1M tokens (same rates for Flare and Sunburst; Batch not supported) (as of 2026-11-05)$xw$, "usageLimits" = $xw$API: Flare is positioned for fast iteration; Sunburst for detailed visual work. Both support image generation and edits (v1/images/generations, v1/images/edits). Batch endpoint is not supported on either model page (as of 2026-11-05). ChatGPT: OpenAI publishes no numeric image limits for plans.$xw$, "updatedAt" = now() WHERE slug = $xw$gpt-image-1-5-dall-e-successor$xw$;
UPDATE platforms SET description = $xw$Moonshot AI's Kimi assistant. Kimi K3.1 Pro is an open-weight, natively multimodal agentic MoE model (about 2.8T total / 104B active parameters) with a 1,048,576-token context, available on the Kimi app and as API model kimi-k3.1-pro on platform.kimi.ai. Weights are on Hugging Face (moonshotai/Kimi-K3.1-Pro) under the Kimi K3.1 Pro License — not a standard open-source license: if you or your affiliates run a Model-as-a-Service business and aggregate revenue exceeds US$20 million over any consecutive 12 months, you need a separate agreement with Moonshot AI before commercial use; commercial products or services with more than 100 million monthly active users or more than US$20 million in monthly revenue must display "Kimi K3.1-Pro" prominently. Kimi 3D Make runs on K3.1 Pro and uses the same membership quota. China-based company. Membership (official pricing page, as of 2026-10-26): Free $0; Plus $15/mo, Pro $31/mo, Max $79/mo, Ultra $159/mo, billed annually; monthly-billing prices not shown. Pay-as-you-go API at platform.kimi.ai. Review data-handling before sending sensitive inputs. (Weights and license checked 2026-11-05.)$xw$, "updatedAt" = now() WHERE slug = $xw$kimi$xw$;
UPDATE platforms SET company = $xw$Cognition$xw$, description = $xw$Devin Desktop (Cognition) is an agentic coding app for local software work, with Devin CLI alongside it. SWE-2 Flash (announced 2026-11-04) is Cognition's faster coding model available in Devin Desktop and Devin CLI; there is no public API and no public weight download. Cognition says it is about one-fifth the price and three times the speed of SWE-2, and is building a program to share weights with trusted partners later. Any free or promo end date for Flash should be confirmed in the in-app model selector (not verified from the Cognition blog alone as of 2026-11-05). Plans: Free $0; Pro $20/mo; Max $200/mo; Teams $80/mo team plan + $40/mo per full seat; Enterprise custom (as of 2026-10-30).$xw$, "updatedAt" = now() WHERE slug = $xw$windsurf$xw$;
UPDATE platforms SET description = $xw$Multi-provider LLM router. Official pricing (openrouter.ai/pricing, as of 2026-10-13): 25+ free models, 50 requests/day; Standard pay-as-you-go plus 5.5% platform fee; Business 8% fee plus EU/US in-region routing; Enterprise custom; BYOK $25k/mo fee-free then 5%. Data-policy routing is paid-only. Whether free-model providers log prompts is unverified. Note (2026-11-05): OpenRouter also lists stealth/crouton-alpha, a free anonymous stealth multimodal model with a 1,048,576-token context for coding and agent sub-tasks; stealth models can be renamed or removed without notice, so it is not a separate Launchpad catalog row.$xw$, "updatedAt" = now() WHERE slug = $xw$openrouter$xw$;
UPDATE platforms SET "keyIntegrations" = $xw$GitHub import, web hosting, database (Neon), Replit Store, Secrets management; Slack (Replit Agent in Slack via workspace bot / @Replit)$xw$, "updatedAt" = now() WHERE slug = $xw$replit-agent$xw$;
UPDATE platforms SET description = $xw$AI built into the Notion workspace: it drafts and improves writing in your pages, transcribes and summarizes meetings, searches across your workspace and connected apps such as Slack and Google Drive, and Notion Agent can take on whole tasks. Notion Agent and Custom Agents can connect to Google Drive (beta) to search, read, write and update Drive files in real time; Notion does not save or index those files, and access follows the connecting user's Drive permissions (help center, as of 2026-11-05). The free plan includes a trial; the full set of AI features comes with the Business and Enterprise plans. AI Meeting Notes can label speakers on the desktop app, most reliably in virtual one-on-one meetings; for Google Meet in Chrome, the Notion Meetings Add-on browser extension adds speaker labels, including in group meetings (desktop only) (as of 2026-10-29).$xw$, "updatedAt" = now() WHERE slug = $xw$notion-ai$xw$;
UPDATE platforms SET description = $xw$An open-source AI agent from Nous Research that you can run on your own computer or server, or have hosted in the cloud through a Nous Portal account. You message it from Telegram, Discord, Slack, WhatsApp, Signal, email or the command line; it keeps a memory, writes its own reusable skills and can run scheduled tasks. The Hermes Marketplace lists community plugins and skills you install with hermes plugins install <name> (hundreds of plugins; count changes over time) (as of 2026-11-05). It is free under the MIT license, and you connect a model provider of your choice. Nous Portal's privacy policy (as of 2026-10-29) says it collects prompts, outputs and conversation history that may be used for training, with a Privacy Mode to opt out of the storage and training use of certain inference payloads; self-hosted, conversations, memories and skills stay on your machine and prompts go to the provider you choose.$xw$, "keyIntegrations" = $xw$Telegram, Discord, Slack, WhatsApp, Signal, email; Hermes Marketplace plugins; MCP servers; model providers including Nous Portal, OpenRouter, OpenAI and custom endpoints; runs locally, in Docker, over SSH, or on Modal, Daytona or Vercel Sandbox$xw$, "updatedAt" = now() WHERE slug = $xw$hermes-agent$xw$;
